import { statSync } from "node:fs";
import type { Failure } from "../../check.ts";
import { repoFileErrorOf } from "../../repo-file-error.ts";
import {
  auditFileError,
  checkedRepoPath,
  isFileErrorOfKind,
  readRepoFile,
  seams,
  walkDir,
} from "./files.ts";
import type { Family } from "./index.ts";
import {
  ATTESTATION_FOOTER,
  ROLLUP_SHAPE_RULE,
  rollupShapeFailures,
} from "./rollup.ts";

// The triage family's rules. The rollup shape rule lives in rollup.ts.

const TRIAGE_ROOT = "skills/triage";
const TEMPLATE_PATH = `${TRIAGE_ROOT}/references/rollup-template.md`;
const CONTRACT_PATH = `${TRIAGE_ROOT}/references/subagent-contract.md`;
const DETECTION_PATH = `${TRIAGE_ROOT}/references/source-detection.md`;
const ISSUE_MODE_PATH = `${TRIAGE_ROOT}/references/issue-mode.md`;

const PRESENT_RULE = "triage-file-present";
const ROUTING_RULE = "triage-detection-routing";
const ENUM_RULE = "triage-enum-mapping";
const FOOTER_RULE = "triage-attestation-footer";
const PREFIX_RULE = "triage-attestation-prefix";
const LEGACY_RULE = "triage-attestation-legacy";
const FENCE_RULE = "triage-attestation-fence";
const ISSUE_MODE_RULE = "triage-attestation-issue-mode";
const EXAMPLE_RULE = "triage-attestation-contract-example";

// The non-ASCII characters of the triage text, built from code points so the source stays ASCII.
const EM = String.fromCodePoint(0x2014);
const ROBOT_FACE = String.fromCodePoint(0x1f916);

/** The footer without its blockquote prefix. */
const BARE_FOOTER = "_Triaged by an AI agent_";
const LEGACY_DISCLAIMER = "This was generated by AI during triage";
const LEGACY_EMOJI_FOOTER = ROBOT_FACE + " _Triaged by";

/** The contract documents the retained structural checks consume, so they are required to exist. */
const TRIAGE_FILES: readonly string[] = [
  TEMPLATE_PATH,
  CONTRACT_PATH,
  DETECTION_PATH,
];

/** Each child directory of these holds one triaged source. */
const SOURCE_PARENTS: readonly string[] = ["references/pull-requests"];
/** These directories are themselves one source. */
const SOURCE_DIRS: readonly string[] = ["references/checks"];

/** Marks a source's emitter inside its directory; the match is case-sensitive. */
const EMITTER_SUFFIX = "-triage.md";

/**
 * The emitters no glob can derive. Whether a file renders a posted comment body has no reliable signal inside the
 * file: carrying the footer is the very thing under audit, so keying on it would make the rule vacuous.
 */
const FIXED_EMITTERS: readonly string[] = [
  "SKILL.md",
  "references/subagent-contract.md",
  "references/rollup-template.md",
  "references/issue-mode.md",
  "references/orchestration-lifecycle.md",
];

/** Opens a source's section inside the rollup. Check sections are keyed by check-run ID, so no list can name them. */
const SECTION_ANCHOR_PREFIX = "<!-- agentics:triage:section:";

/**
 * The adapters whose only output is a rollup section. They carry no footer, because the rollup closes with the only
 * one, and must name a section anchor instead. Pinned by path so a thread-reply adapter that merely mentions an anchor
 * keeps the strict footer rule.
 */
const SECTION_EMITTERS: ReadonlySet<string> = new Set([
  "references/checks/checks-triage.md",
  "references/pull-requests/checkmarx/checkmarx-triage.md",
  "references/pull-requests/merge-conflicts/merge-conflicts-triage.md",
]);

// White space is tab, LF, FF, CR and space only, so SPACE spells it out where JavaScript's \s would add the vertical
// tab and Unicode spaces. A line starts only after LF, where JavaScript's m flag would also start one after CR, U+2028
// and U+2029, so the patterns spell a line start as a lookbehind. None of the patterns is case-insensitive.
const SPACE = "[\\t\\n\\f\\r ]";
const LINE_START = "(?<=^|\\n)";

// An enum row, applied to one line at a time, so ^ and $ bound the line.
const ENUM_ROW_RE = new RegExp(
  `^\\|${SPACE}*\`([a-z_-]+)\`${SPACE}*\\|([^|]*)\\|([^|]*)\\|${SPACE}*$`,
  "u",
);
// The header of the per-source mapping table.
const MAPPING_HEADER_RE = new RegExp(
  `${LINE_START}\\| Source${SPACE}+\\| Fixed`,
  "u",
);
// A rendered text or markdown fence, and an issue-mode markdown fence; the first capture ends before the closing fence.
const MARKERED_FENCE_RE = new RegExp(
  `${LINE_START}\`\`\`(?:text|markdown)\\n(.*?)${LINE_START}\`\`\``,
  "gsu",
);
const ISSUE_FENCE_RE = new RegExp(
  `${LINE_START}\`\`\`markdown\\n(.*?)${LINE_START}\`\`\``,
  "gsu",
);
// The lines that open and close the bot routing table, matched one line at a time.
const ROUTING_START = "### Bot routing table";
const ROUTING_END = "**Marker-keyed";

function escapeRegExp(text: string): string {
  return text.replace(/[\\^$.*+?()[\]{}|]/g, "\\$&");
}

// The contract example's body. Its two `\\n` match a literal backslash followed by `n`, twice: the JSON
// example spells its line breaks as escapes, not as line breaks.
const CONTRACT_EXAMPLE_RE = new RegExp(
  `"body": "<!-- agentics:triage:[^"]*?\\\\n\\\\n${escapeRegExp(ATTESTATION_FOOTER)}"`,
  "u",
);

// The legacy footer that linked the attribution to the Agentics repository.
const LEGACY_LINKED_FOOTER_RE = /_Triaged by \[Agentics\]\(/u;

/** The audit error for a failure to read `rel`: the file error's own text, with no prefix. */
function readError(rel: string, error: unknown): Error {
  const fileError = repoFileErrorOf(error, rel);
  return new Error(fileError.message, { cause: fileError });
}

/** `readRepoFile` whose failures are audit errors carrying the file error's text. */
function readText(repoRoot: string, rel: string): string {
  try {
    return readRepoFile(repoRoot, rel);
  } catch (error) {
    throw readError(rel, error);
  }
}

/** The lines of `block` that hold more than white space, kept as they are. */
function nonBlankLines(block: string): string[] {
  return block.split("\n").filter((line) => line.trim() !== "");
}

/** The offsets of every non-overlapping occurrence of `needle` in `line`. */
function findAll(line: string, needle: string): number[] {
  const found: number[] = [];
  let from = 0;
  for (;;) {
    const at = line.indexOf(needle, from);
    if (at < 0) return found;
    found.push(at);
    from = at + needle.length;
  }
}

function isSectionMarker(line: string): boolean {
  return line.startsWith(SECTION_ANCHOR_PREFIX);
}

/**
 * The triage-enum-mapping rule: every disposition value in the contract's enum has a rule in the rollup's per-source
 * mapping block. A Human Feedback value is exempt, because that row counts the developer's decision, so the row is
 * checked for the three decisions instead. The early returns and the messages come in this order: too few values, then
 * no mapping table, then the Human Feedback decisions, then the sorted list of unmapped values.
 */
function enumMappingRule(repoRoot: string): Failure[] {
  const failures: Failure[] = [];
  const contract = readText(repoRoot, CONTRACT_PATH);
  const rollup = readText(repoRoot, TEMPLATE_PATH);

  const usedBy = new Map<string, string>();
  const order: string[] = [];
  for (const line of contract.split("\n")) {
    const row = ENUM_ROW_RE.exec(line);
    if (row === null) continue;
    const value = row[1] ?? "";
    if (!usedBy.has(value)) order.push(value);
    usedBy.set(value, (row[3] ?? "").trim());
  }
  if (usedBy.size < 8)
    return [
      {
        rule: ENUM_RULE,
        path: CONTRACT_PATH,
        message: `parsed only ${usedBy.size} enum values ${EM} table shape changed?`,
      },
    ];

  const notFound: Failure = {
    rule: ENUM_RULE,
    path: TEMPLATE_PATH,
    message: "could not locate the rollup per-source mapping table",
  };
  const header = MAPPING_HEADER_RE.exec(rollup);
  if (header === null) return [notFound];
  const rest = rollup.slice(header.index);
  const end = rest.indexOf("\n\n");
  if (end < 0) return [notFound];
  const mapping = rest.slice(0, end);

  const missing: string[] = [];
  for (const value of order) {
    if ((usedBy.get(value) ?? "").includes("Human Feedback")) continue;
    if (!mapping.includes(`\`${value}\``) && !mapping.includes(`"${value}"`))
      missing.push(value);
  }
  let humanFeedback = "";
  for (const line of mapping.split("\n"))
    if (line.startsWith("| Human Feedback")) humanFeedback = line;
  for (const decision of ["accepted", "accepted-edited", "skipped"])
    if (!humanFeedback.includes(`\`${decision}\``))
      failures.push({
        rule: ENUM_RULE,
        path: TEMPLATE_PATH,
        message: `Human Feedback mapping row does not name decision \`${decision}\``,
      });
  if (missing.length > 0) {
    missing.sort();
    failures.push({
      rule: ENUM_RULE,
      path: TEMPLATE_PATH,
      message: `dispositions with no rollup mapping rule: ${missing.join(", ")}`,
    });
  }
  return failures;
}

/** The entries of a source directory, with an audit error for a path that is linked, missing or unreadable. */
function listSource(repoRoot: string, rel: string) {
  const full = `${TRIAGE_ROOT}/${rel}`;
  let dir: string;
  try {
    dir = checkedRepoPath(repoRoot, full);
  } catch (error) {
    throw auditFileError("reading", full, error);
  }
  try {
    return seams.readDir(dir);
  } catch (error) {
    throw auditFileError("reading", full, repoFileErrorOf(error, full));
  }
}

/**
 * The skill-relative emitter paths, the fixed emitters plus the one derived emitter of each triaged source, in default
 * sort order, together with a failure for each source directory that holds no emitter. A source is a real directory
 * below a source parent, or one of the source directories. A link is never a source. The list of sources is never
 * empty, because `SOURCE_DIRS` always names one, so there is no zero-source audit error.
 */
function resolveEmitters(repoRoot: string): {
  emitters: string[];
  failures: Failure[];
} {
  const sources: string[] = [];
  for (const parent of SOURCE_PARENTS)
    for (const entry of listSource(repoRoot, parent))
      if (!entry.isSymlink && entry.isDirectory)
        sources.push(`${parent}/${entry.name}`);
  sources.push(...SOURCE_DIRS);
  sources.sort();

  const seen = new Set<string>(FIXED_EMITTERS);
  const failures: Failure[] = [];
  for (const source of sources) {
    let found = 0;
    for (const entry of listSource(repoRoot, source)) {
      if (
        !entry.isSymlink &&
        !entry.isDirectory &&
        entry.name.endsWith(EMITTER_SUFFIX)
      ) {
        seen.add(`${source}/${entry.name}`);
        found += 1;
      }
    }
    if (found === 0)
      failures.push({
        rule: FOOTER_RULE,
        path: `${TRIAGE_ROOT}/${source}`,
        message: `triaged source directory holds no *${EMITTER_SUFFIX} emitter`,
      });
  }
  return { emitters: [...seen].sort(), failures };
}

/** The repo-relative paths of the `.md` files below `skills/triage`, in default sort order. */
function markdownFiles(repoRoot: string): string[] {
  const files: string[] = [];
  let root: string;
  try {
    root = checkedRepoPath(repoRoot, TRIAGE_ROOT);
  } catch (error) {
    if (isFileErrorOfKind(error, "symlink"))
      throw auditFileError("walking", TRIAGE_ROOT, error);
    return files;
  }
  try {
    if (!statSync(root).isDirectory()) return files;
  } catch {
    return files;
  }
  try {
    walkDir(
      root,
      (inner, entry) => {
        if (entry.isDirectory || entry.isSymlink) return;
        if (inner.endsWith(".md")) files.push(`${TRIAGE_ROOT}/${inner}`);
      },
      TRIAGE_ROOT,
    );
  } catch (error) {
    throw auditFileError("walking", TRIAGE_ROOT, error);
  }
  return files.sort();
}

/**
 * The attestation rules: the footer is byte-exact, blockquoted exactly one level, last in
 * every rendered comment body, and the superseded forms are gone. Emitters come first, in default sort order, then every
 * `.md` file below the skill in default sort order, then the issue-mode templates and the contract example.
 */
function attestationRules(repoRoot: string): Failure[] {
  const failures: Failure[] = [];
  const resolved = resolveEmitters(repoRoot);
  failures.push(...resolved.failures);
  for (const rel of resolved.emitters) {
    const full = `${TRIAGE_ROOT}/${rel}`;
    let text: string;
    try {
      text = readRepoFile(repoRoot, full);
    } catch (error) {
      if (isFileErrorOfKind(error, "missing")) {
        failures.push({
          rule: FOOTER_RULE,
          path: full,
          message: "emitter listed in the guard does not exist",
        });
        continue;
      }
      throw readError(full, error);
    }
    if (SECTION_EMITTERS.has(rel)) {
      if (!text.includes(SECTION_ANCHOR_PREFIX))
        failures.push({
          rule: FOOTER_RULE,
          path: full,
          message: `section emitter names no ${SECTION_ANCHOR_PREFIX} anchor`,
        });
      continue;
    }
    if (!text.includes(ATTESTATION_FOOTER))
      failures.push({
        rule: FOOTER_RULE,
        path: full,
        message: "missing the exact attestation footer",
      });
  }

  let markered = 0;
  for (const rel of markdownFiles(repoRoot)) {
    const text = readText(repoRoot, rel);

    // Every bare-footer occurrence sits directly behind `> `, one level.
    for (const [index, line] of text.split("\n").entries()) {
      for (const at of findAll(line, BARE_FOOTER)) {
        const prefix = line.slice(0, at);
        if (!prefix.endsWith("> "))
          failures.push({
            rule: PREFIX_RULE,
            path: rel,
            message: `line ${index + 1}: footer missing its \`> \` blockquote prefix: ${JSON.stringify(line)}`,
          });
        else if (prefix.endsWith("> > "))
          failures.push({
            rule: PREFIX_RULE,
            path: rel,
            message: `line ${index + 1}: footer nested deeper than one blockquote level: ${JSON.stringify(line)}`,
          });
      }
    }

    // Superseded forms are gone everywhere.
    if (text.includes(LEGACY_DISCLAIMER))
      failures.push({
        rule: LEGACY_RULE,
        path: rel,
        message: "retains the superseded leading disclaimer",
      });
    if (text.includes(LEGACY_EMOJI_FOOTER))
      failures.push({
        rule: LEGACY_RULE,
        path: rel,
        message: "retains the superseded emoji-prefixed footer",
      });
    if (LEGACY_LINKED_FOOTER_RE.test(text))
      failures.push({
        rule: LEGACY_RULE,
        path: rel,
        message:
          "retains the superseded footer that links to the Agentics repository",
      });

    // Marker first, footer last, on rendered comment bodies.
    for (const fence of text.matchAll(MARKERED_FENCE_RE)) {
      const block = fence[1] ?? "";
      const lines = nonBlankLines(block);
      const first = lines[0];
      if (first === undefined || !first.startsWith("<!-- agentics:triage:"))
        continue;
      if (isSectionMarker(first)) {
        if (block.includes(ATTESTATION_FOOTER))
          failures.push({
            rule: FENCE_RULE,
            path: rel,
            message: `embedded section ${first} must not carry its own footer`,
          });
        continue;
      }
      markered += 1;
      const last = lines[lines.length - 1] ?? "";
      if (last !== ATTESTATION_FOOTER)
        failures.push({
          rule: FENCE_RULE,
          path: rel,
          message: `markered fence must close with the footer (ends ${JSON.stringify(last)})`,
        });
    }
  }
  // Four comment bodies close with the footer: the rollup and the three thread-reply adapters. Checks and Checkmarx
  // render rollup sections.
  if (markered < 4)
    failures.push({
      rule: FENCE_RULE,
      path: TRIAGE_ROOT,
      message: `parsed only ${markered} markered comment-body fences ${EM} shape changed?`,
    });

  // Issue-mode disposition templates are posted comments with no marker, so their footer order is checked directly.
  // Only a link on the way is an error here: any other read failure was already raised when the file was audited as an
  // emitter, or leaves the file out of this check.
  let issueMode: string | undefined;
  try {
    issueMode = readRepoFile(repoRoot, ISSUE_MODE_PATH);
  } catch (error) {
    if (isFileErrorOfKind(error, "symlink")) throw error;
  }
  if (issueMode !== undefined) {
    let fences = 0;
    for (const fence of issueMode.matchAll(ISSUE_FENCE_RE)) {
      fences += 1;
      const lines = nonBlankLines(fence[1] ?? "");
      const last = lines[lines.length - 1] ?? "";
      if (last !== ATTESTATION_FOOTER)
        failures.push({
          rule: ISSUE_MODE_RULE,
          path: ISSUE_MODE_PATH,
          message: `disposition template must close with the footer (ends ${JSON.stringify(last)})`,
        });
    }
    if (fences < 4)
      failures.push({
        rule: ISSUE_MODE_RULE,
        path: ISSUE_MODE_PATH,
        message: `parsed only ${fences} issue-mode disposition templates ${EM} shape changed?`,
      });
  }

  // The contract's JSON example shows the same ordering.
  let contract: string | undefined;
  try {
    contract = readRepoFile(repoRoot, CONTRACT_PATH);
  } catch (error) {
    if (isFileErrorOfKind(error, "symlink")) throw error;
  }
  if (contract !== undefined && !CONTRACT_EXAMPLE_RE.test(contract))
    failures.push({
      rule: EXAMPLE_RULE,
      path: CONTRACT_PATH,
      message:
        "JSON example body must open with the marker and close with the footer",
    });
  return failures;
}

/**
 * Whether `rel` is a regular file the content checks can read. A path that cannot be inspected, or that is a
 * directory, counts as missing; a link on the way is an audit error instead.
 */
function isPresent(repoRoot: string, rel: string): boolean {
  let file: string;
  try {
    file = checkedRepoPath(repoRoot, rel);
  } catch (error) {
    if (isFileErrorOfKind(error, "symlink"))
      throw auditFileError("checking", rel, error);
    return false;
  }
  try {
    return !statSync(file).isDirectory();
  } catch {
    return false;
  }
}

/**
 * Every rule of the triage family. The findings come out in this order, with no sort: presence, enum mapping, rollup
 * shape, attestation, detection routing. A missing contract file skips only the content checks that read it, because
 * presence reports it; the attestation rules run regardless.
 */
function triageRules(repoRoot: string): Failure[] {
  const failures: Failure[] = [];
  const present = new Set<string>();
  for (const rel of TRIAGE_FILES) {
    if (isPresent(repoRoot, rel)) present.add(rel);
    else
      failures.push({
        rule: PRESENT_RULE,
        path: rel,
        message: "required triage contract file is missing",
      });
  }

  if (present.has(CONTRACT_PATH) && present.has(TEMPLATE_PATH))
    failures.push(...enumMappingRule(repoRoot));
  if (present.has(TEMPLATE_PATH))
    failures.push(...rollupShapeFailures(repoRoot));
  failures.push(...attestationRules(repoRoot));

  // The bot routing table must not regain a checkmarx login row.
  if (present.has(DETECTION_PATH)) {
    let inTable = false;
    for (const [index, line] of readText(repoRoot, DETECTION_PATH)
      .split("\n")
      .entries()) {
      if (line.startsWith(ROUTING_START)) inTable = true;
      if (line.startsWith(ROUTING_END)) inTable = false;
      if (
        inTable &&
        line.startsWith("|") &&
        line.toLowerCase().includes("checkmarx")
      )
        failures.push({
          rule: ROUTING_RULE,
          path: DETECTION_PATH,
          message: `line ${index + 1}: bot routing table must not carry a checkmarx login row ${EM} detection is marker-keyed`,
        });
    }
  }
  return failures;
}

/**
 * The `triage` family: the disposition enum and the rollup mapping agree, the rendered rollup has its pinned shape,
 * every emitter closes with the byte-exact AI attestation footer, and the bot routing table stays marker-keyed.
 */
export const FAMILY: Family = {
  name: "triage",
  rules: [
    PRESENT_RULE,
    ROUTING_RULE,
    ENUM_RULE,
    ROLLUP_SHAPE_RULE,
    FOOTER_RULE,
    PREFIX_RULE,
    LEGACY_RULE,
    FENCE_RULE,
    ISSUE_MODE_RULE,
    EXAMPLE_RULE,
  ],
  run: (repoRoot) => triageRules(repoRoot),
};
